declarations.type:
∀ {𝕜 : Type u_1} [inst : NontriviallyNormedField 𝕜] [inst_1 : CompleteSpace 𝕜] {V : Type u_2}
  [inst_2 : NormedAddCommGroup V] [inst_3 : NormedSpace 𝕜 V] [inst_4 : FiniteDimensional 𝕜 V] (g : V [×2]→L[𝕜] 𝕜),
  continuousBilinearMapOfContinuousMultilinearMap g =
    { toFun := fun x => { toFun := fun y => g.toFun ![x, y], map_add' := ⋯, map_smul' := ⋯, cont := ⋯ }, map_add' := ⋯,
      map_smul' := ⋯, cont := ⋯ }

∀ {𝕜 : Type u_1} [inst : NontriviallyNormedField 𝕜] [inst_1 : CompleteSpace 𝕜] {V : Type u_2}
  [inst_2 : NormedAddCommGroup V] [inst_3 : NormedSpace 𝕜 V] [inst_4 : FiniteDimensional 𝕜 V] (g g_1 : V [×2]→L[𝕜] 𝕜),
  g = g_1 → continuousBilinearMapOfContinuousMultilinearMap g = continuousBilinearMapOfContinuousMultilinearMap g_1

∀ {V : Type u_1} [inst : NormedAddCommGroup V] [inst_1 : NormedSpace ℝ V] {f : V → ℝ} {x₀ : V}
  {p : FormalMultilinearSeries ℝ V ℝ} {r : NNReal},
  HasFPowerSeriesOnBall f p x₀ ↑r → (fun x => f x - p.partialSum 3 (x - x₀)) =o[nhds x₀] fun x => ‖x - x₀‖ ^ 2

∀ {𝕜 : Type u_2} [inst : NontriviallyNormedField 𝕜] [CompleteSpace 𝕜] {V : Type u_1} [inst_2 : NormedAddCommGroup V]
  [inst_3 : NormedSpace 𝕜 V] [FiniteDimensional 𝕜 V] (g : V [×2]→L[𝕜] 𝕜),
  Continuous fun x => { toFun := fun y => g.toFun ![x, y], map_add' := ⋯, map_smul' := ⋯, cont := ⋯ }

∀ {𝕜 : Type u_1} [inst : NontriviallyNormedField 𝕜] {E : Type u_2} [inst_1 : NormedAddCommGroup E]
  [inst_2 : NormedSpace 𝕜 E] {F : Type u_3} [inst_3 : NormedAddCommGroup F] [inst_4 : NormedSpace 𝕜 F] {f : E → F}
  {f' : E →L[𝕜] F} {x : E}, HasFDerivAt f f' x = (fun h => f (x + h) - f x - f' h) =o[nhds 0] fun h => h
